import * as THREE from 'three/webgpu';
import { texture, uv, vec4, float, mix, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const width = 1.8;
  const height = 1.8 * (320 / 512);

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const imageUrl = (config.assets && config.assets.imageUrl) || '/prism-mock/home/nodes/orb-decor.png';
  const map = ctx.textureLoader.load(imageUrl);
  map.colorSpace = THREE.SRGBColorSpace;

  const uvNode = uv();
  const texColor = texture(map, uvNode);

  // engineered gradient overlay: ink -> surface, subtle vertical gradient, no soft blur
  const ink = vec4(0x16 / 255, 0x16 / 255, 0x1d / 255, 1.0);
  const surface = vec4(0x0b / 255, 0x0b / 255, 0x10 / 255, 1.0);
  const gradientFactor = uvNode.y;
  const gradient = mix(surface, ink, gradientFactor);

  // subtle grain via hashed noise from uv coords
  const grainAmount = uniform(0.03);
  const grainSeed = uvNode.x.mul(1000.0).add(uvNode.y.mul(1000.0)).sin().mul(43758.5453).fract();
  const grain = grainSeed.sub(0.5).mul(grainAmount);

  const blended = mix(texColor, gradient, float(0.12)).add(vec4(grain, grain, grain, 0.0));

  material.colorNode = blended;
  material.opacityNode = texColor.a;

  const mesh = new THREE.Mesh(geometry, material);

  mesh.position.set(0, -0.3, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
  };

  return mesh;
}
